pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(seed != 0);
        vm.warp(seed);
        vm.roll(seed);
        uint256 r = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(r == 0); // force the winning branch so the payout/reset path is exercised

        uint256 ticket = 10; // matches public constant TICKET_AMOUNT, required by require()
        vm.deal(actor, ticket);
        vm.prank(actor);
        c.play{value: ticket}();

        // General rule: on a win, the whole pot is paid out and the pot is reset to zero,
        // and the contract retains no leftover funds.
        assertTrue(c.pot() == 0 && address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // plain EOA player, transfer to it always succeeds
        vm.assume(value <= address(actor).balance + type(uint256).max / 2);
        vm.deal(actor, value);
        uint256 potBefore = c.pot();
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        bool ok;
        try c.play{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            // Accepted play: the recorded pot must track the actual ETH held by the
            // contract. A non-winning play adds the paid-in value to both; a winning
            // play pays out pot (fee to bank, pot-fee to player) and zeroes pot.
            // So in either outcome the recorded pot still equals the real balance.
            assertTrue(address(c).balance == c.pot(), "pot must equal contract balance after an accepted play");
        } else {
            // Rejected play: nothing changes at all.
            assertTrue(c.pot() == potBefore && address(c).balance == balBefore, "rejected play must not change state");
        }
    }
}

