pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.warp(ts);
        vm.roll(diff);

        uint potBefore = c.pot();
        uint balBefore = address(c).balance;
        uint256 amount = 10; // TICKET_AMOUNT enforced by require

        vm.deal(actor, amount);
        vm.prank(actor);
        c.play{value: amount}();

        uint random = uint(keccak256(abi.encodePacked(ts, diff))) % 2;
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        if (random == 0) {
            // winning round: pot fully paid out, contract keeps only the fee,
            // and the payout the winner could receive equals what was credited.
            assertTrue(potAfter == 0 && balAfter == balBefore + 1);
        } else {
            // losing round: every wei retained by the contract must be recorded in pot.
            assertTrue(balAfter == balBefore + potAfter && potAfter == potBefore + amount);
        }
    }
}

