pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(ts < type(uint64).max - 300);

        // advance time until the pseudo-random outcome is a win (random == 0),
        // mirroring the contract's own randomness source
        bool win = false;
        for (uint256 t = ts; t < ts + 256; t++) {
            vm.warp(t);
            uint256 r = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (r == 0) { win = true; break; }
        }
        vm.assume(win);

        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10, gas: 100000}() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.pot() == 0 && address(c).balance == 1);
    }
}

