pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, address actor) public {
        // Admissible domain: play() only accepts an exact ticket payment of 10 wei.
        vm.assume(value == 10);
        vm.assume(actor != address(0) && actor != address(c));

        vm.deal(actor, 1 ether);

        bool ok;
        vm.prank(actor);
        try c.play{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule the reference always satisfies for an accepted play:
        // either the round was a win (pot fully paid out: recorded pot is 0 and the
        // contract retains exactly the 1-wei fee) or a loss (the recorded pot exactly
        // matches the real ETH balance of the contract).
        assertTrue(
            !ok ||
            (c.pot() == 0 && address(c).balance == 1) ||
            address(c).balance == c.pot(),
            "recorded pot must match real held ETH after an accepted play"
        );
    }
}

