pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 diff) public {
        // keep domain wide but forgeable
        ts = bound(ts, 1, block.timestamp + 1_000_000);
        diff = bound(diff, 1, 1_000_000);
        vm.warp(ts);
        vm.roll(diff);

        uint256 random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random == 0);

        address player = address(0xA11CE);
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();

        // general rule: on a winning random draw the pot is fully paid out and reset to zero
        assertTrue(c.pot() == 0);
    }
}

